import sys


class N:
    __slots__ = ("k", "l", "r")

    def __init__(self, k):
        self.k = k
        self.l = None
        self.r = None


def main():
    root = None
    out = []
    for line in sys.stdin.read().split("\n"):
        p = line.split()
        if not p:
            continue
        c = p[0]
        if c == "insert":
            x = int(p[1])
            if root is None:
                root = N(x)
                out.append("ok")
                continue
            n = root
            while True:
                if x == n.k:
                    out.append("dup")
                    break
                if x < n.k:
                    if n.l is None:
                        n.l = N(x)
                        out.append("ok")
                        break
                    n = n.l
                else:
                    if n.r is None:
                        n.r = N(x)
                        out.append("ok")
                        break
                    n = n.r
        elif c == "contains":
            x = int(p[1])
            n = root
            while n is not None and n.k != x:
                n = n.l if x < n.k else n.r
            out.append("yes" if n else "no")
        elif c == "delete":
            x = int(p[1])
            par = None
            n = root
            while n is not None and n.k != x:
                par = n
                n = n.l if x < n.k else n.r
            if n is None:
                out.append("missing")
                continue
            if n.l is not None and n.r is not None:
                sp = n
                s = n.r
                while s.l is not None:
                    sp = s
                    s = s.l
                n.k = s.k
                if sp is n:
                    sp.r = s.r
                else:
                    sp.l = s.r
            else:
                ch = n.l if n.l is not None else n.r
                if par is None:
                    root = ch
                elif par.l is n:
                    par.l = ch
                else:
                    par.r = ch
            out.append("ok")
        elif c == "inorder":
            res = []
            st = []
            n = root
            while st or n is not None:
                while n is not None:
                    st.append(n)
                    n = n.l
                n = st.pop()
                res.append(n.k)
                n = n.r
            out.append(" ".join(map(str, res)) if res else "<empty>")
        elif c == "height":
            h = 0
            lvl = [root] if root else []
            while lvl:
                h += 1
                nxt = []
                for n in lvl:
                    if n.l:
                        nxt.append(n.l)
                    if n.r:
                        nxt.append(n.r)
                lvl = nxt
            out.append(str(h))
        elif c == "min":
            if root is None:
                out.append("empty")
            else:
                n = root
                while n.l:
                    n = n.l
                out.append(str(n.k))
        elif c == "max":
            if root is None:
                out.append("empty")
            else:
                n = root
                while n.r:
                    n = n.r
                out.append(str(n.k))
    print("\n".join(out))


main()
